import { renderGrammar } from './grammar.js';
import { hosted, requestAPI, assetURL, sourceURL, startBrowserAI, stopBrowserAI } from './runtime.js';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey = 'margin-sat-v1';
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};
function recentContext(){let total=0;const result=[];for(const m of [...state.messages].reverse()){if(result.length>=16||total+m.content.length>32000)break;result.unshift(m);total+=m.content.length;}while(result[0]?.role==='assistant')result.shift();return result;}
function readSaved(){try{const p=JSON.parse(localStorage.getItem(storageKey)||'{}');return {messages:Array.isArray(p.messages)?p.messages.filter(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string').slice(-30):[],history:Array.isArray(p.history)?p.history:[],mistakes:Array.isArray(p.mistakes)?p.mistakes:[],completed:Array.isArray(p.completed)?p.completed:[],style:['quick','detailed','socratic'].includes(p.style)?p.style:'detailed'};}catch{return {messages:[],history:[],mistakes:[],completed:[],style:'detailed'};}}
const extraSaved=(()=>{try{return JSON.parse(localStorage.getItem(storageKey)||'{}');}catch{return {};}})();
const state={...readSaved(),questionId:extraSaved.questionId||null,profile:extraSaved.profile||{minutes:45,goal:'',testDate:''},officialLog:Array.isArray(extraSaved.officialLog)?extraSaved.officialLog:[],bundles:null,bundleChoice:{test:6,section:'math',module:1,number:1},official:null,officialReveal:false,lessons:[],health:null,route:'home',filter:'All',search:'',quiz:null,quizBusy:false,chatBusy:false,chatError:'',quizError:'',controller:null,quizDraft:{topic:'',count:5,difficulty:'Mixed',source:hosted?'practice':'ai'}};
function save(){try{localStorage.setItem(storageKey,JSON.stringify({questionId:state.questionId,profile:state.profile,officialLog:state.officialLog,messages:state.messages.slice(-30),history:state.history.slice(0,100),mistakes:state.mistakes.slice(0,200),completed:state.completed,style:state.style}));}catch{toast('Browser storage is full. This session still works, but new progress may not save.');}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3600);}
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',tutor:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 10h9M7 14h6"/>',quiz:'<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>',library:'<path d="M12 5v16M12 5C8 2 3 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-1-7-2-10 1Z"/>',review:'<path d="M8 3H5a2 2 0 0 0-2 2v15a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-3"/><rect x="8" y="1" width="8" height="5" rx="1.5"/><path d="m7 14 3 3 7-7"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.library}</svg>`;}
let md;
function markdown(text){md ||= window.markdownit({html:false,linkify:true,breaks:true});return md.render(String(text));}
function typeset(root=$('#main')){if(window.renderMathInElement)window.renderMathInElement(root,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false},{left:'$',right:'$',display:false}],throwOnError:false});$$('a',root).forEach(a=>{if(/^https?:/.test(a.href)){a.target='_blank';a.rel='noopener noreferrer';}});}
const api = requestAPI;
async function checkHealth(){try{state.health=await api('/api/health');}catch{state.health={ready:false,message:'The app server is unavailable. Restart Margin and refresh this page.'};}$('.status-dot').classList.toggle('ready',!!state.health.ready);$('#connection-title').textContent=state.health.ready?'Your tutor is ready':'Tutor needs a connection';$('#connection-sub').textContent=state.health.ready?(state.health.provider==='browser'?'Browser AI · on this device':state.health.provider==='ollama'?'Local AI · on this Mac':'Connected AI'):'Lessons & practice still work';$('#settings-status').textContent=state.health.message||`${state.health.model||'AI'} is ready.`;return state.health;}
function navigate(path){if(location.hash==='#'+path)renderRoute();else location.hash=path;}
const navItems=[['home','Overview'],['grammar','Grammar Academy'],['tutor','AI tutor'],['quiz','Quiz studio'],['bundles','Your SAT tests'],['library','Study library'],['plan','Study plan'],['review','My progress']];
function renderNav(){const route=state.route.split('/')[0];$('#navigation').innerHTML=navItems.map(([id,label])=>`<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''} title="${label}">${icon(id)}<span>${label}</span>${id==='review'&&state.mistakes.filter(m=>!m.resolved).length?`<span class="count">${state.mistakes.filter(m=>!m.resolved).length}</span>`:''}</a>`).join('');$('#page-name').textContent=navItems.find(([id])=>id===route)?.[1]||'Study library';}
function heading(eyebrow,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function heroArt(){return `<svg viewBox="0 0 270 230" role="img" aria-label="A stack of study books, a pencil, and a rising sun"><circle cx="155" cy="94" r="69" fill="#dce3ce"/><path d="M88 185h155" stroke="#b5c0a3"/><g transform="rotate(-10 156 142)"><path d="M75 130h147v29H75c-17 0-17-29 0-29Z" fill="#688068"/><path d="M77 135h141v18H77c-10 0-10-18 0-18Z" fill="#f7f5e9"/><path d="M79 143h131m-131 5h121" stroke="#d9decb"/><path d="M65 103h147v25H65c-15 0-15-25 0-25Z" fill="#bc7452"/><path d="M67 108h139v15H67c-8 0-8-15 0-15Z" fill="#f8f2e6"/><path d="M83 78h127v23H83c-14 0-14-23 0-23Z" fill="#a9b985"/><path d="M84 83h121v12H84c-6 0-6-12 0-12Z" fill="#f9f6e9"/></g><path d="m195 53 12 4-38 105-13 12-1-18Z" fill="#d7b372"/><path d="m195 53 5 2-37 103-7-2Z" fill="#e7ca8c"/><path d="m156 174 5-4-5-3Z" fill="#3b5745"/><path d="m196 52 3-8c2-5 14-1 12 4l-3 9Z" fill="#c98976"/><path d="M73 53v-16m-8 8h16M232 110v-12m-6 6h12" stroke="#9eae8b" stroke-width="1.5"/><circle cx="83" cy="176" r="3" fill="#bc7657"/><path d="M99 32c13-9 40-8 52 1" stroke="#b8c7a4" fill="none" stroke-dasharray="3 4"/><path d="m141 26 11 7-11 3" fill="none" stroke="#b8c7a4"/></svg>`;}
function renderHome(){const main=$('#main');main.innerHTML=heading('SAT MATH + READING & WRITING','Big goals. Small steps.','Your SAT journey, with a study partner by your side.',`<span class="day-tag">✧ Make today count</span>`)+`<div class="home-actions"><button class="button primary" data-go="grammar">Grammar Academy · Start learning →</button><button class="button" data-go="bundles">Your 960 official questions ↗</button><button class="button ghost" data-go="plan">Today’s study plan →</button><button class="button ghost" id="start-diagnostic">Find my weak skills →</button></div><section class="hero"><div class="hero-content"><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h2>A clearer path to<br>“I finally get it.”</h2><p>Ask the questions. Untangle the hard parts.<br>Build your confidence, one concept at a time.</p><button class="button primary" data-go="tutor">Study with your AI tutor <span>↗</span></button></div><div class="hero-art">${heroArt()}</div></section><div class="section-top"><h2>How do you want to learn today?</h2><span class="muted" style="font-size:10px">Your pace. Your path.</span></div><div class="feature-grid">${[['tutor','Talk it through','A patient tutor. Clear explanations. As many questions as you need.'],['quiz','Put it into practice','Turn any topic into a quiz made for what you want to learn.'],['library','Build your foundation','Simple lessons, worked examples, and the rules worth remembering.']].map(([id,title,desc])=>`<button class="feature" data-go="${id}"><span class="feature-icon">${icon(id)}</span><span class="feature-arrow">↗</span><h3>${title}</h3><p>${desc}</p></button>`).join('')}</div><div class="home-bottom"><section><div class="section-top"><h2>${state.completed.length?'Keep the momentum':'A good place to begin'}</h2><button class="text-link" data-go="library">View library →</button></div><div class="path-card">${state.lessons.filter(l=>!state.completed.includes(l.id)).slice(0,3).map((l,i)=>`<div class="path-row"><span class="path-num">0${i+1}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.category)} · ${l.minutes} min read</p></div><button class="text-link" data-lesson="${esc(l.id)}">Start ↗</button></div>`).join('')||'<div class="path-row">All lessons complete. Revisit a favorite or try a fresh quiz.</div>'}</div></section><section><div class="section-top"><h2>A note for today</h2></div><div class="tip-card"><div class="eyebrow">THE POWER OF A GOOD MISTAKE</div><p>Don’t just check the answer.<br>Find the moment your<br>thinking took a turn.</p><small>That’s where the learning happens. ↗</small></div></section></div>`;bindGo();}
function bindGo(){if($('#start-diagnostic'))$('#start-diagnostic').onclick=startDiagnostic;$$('[data-go]').forEach(el=>el.onclick=()=>navigate(el.dataset.go));$$('[data-lesson]').forEach(el=>el.onclick=()=>navigate('library/'+el.dataset.lesson));}
function renderLibrary(){const main=$('#main');main.innerHTML=heading('KNOWLEDGE, AT YOUR PACE','Make the hard parts click.','A library of clear lessons, original examples, and practice from your SAT bundles.',`<button class="button small" id="open-guide">Full study guide ↗</button>`)+`<div class="library-toolbar"><div class="filter-row">${['All','Math','Reading','Writing','Strategy'].map(c=>`<button class="chip ${state.filter===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div><input class="search" type="search" id="lesson-search" placeholder="Find a concept…" aria-label="Search lessons" value="${esc(state.search)}"></div><div class="lesson-grid" id="lesson-grid"></div>`;renderLessonCards();$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderLibrary();});$('#lesson-search').oninput=e=>{state.search=e.target.value;renderLessonCards();};$('#open-guide').onclick=()=>navigate('library/guide');}
function renderLessonCards(){const list=state.lessons.filter(l=>(state.filter==='All'||l.category===state.filter)&&`${l.title} ${l.description} ${l.tags?.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));$('#lesson-grid').innerHTML=list.length?list.map(l=>`<button class="lesson-card" data-lesson="${esc(l.id)}"><span class="lesson-tag">${esc(l.category)}</span><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p><span class="lesson-meta"><span>${l.minutes} min read ${state.completed.includes(l.id)?' · ✓ Completed':''}</span><span>Open lesson ↗</span></span></button>`).join(''):'<div class="empty-state"><h2>No lessons found.</h2><p>Try another topic or clear your search.</p></div>';bindGo();}
async function renderLesson(id){const main=$('#main');const lesson=state.lessons.find(l=>l.id===id);if(id==='guide'){main.innerHTML='<div class="loading">Opening your study guide…</div>';try{const data=await api('/api/guide');if(state.route!=='library/guide')return;main.innerHTML=`<div class="article-shell"><button class="text-link" data-go="library">← Back to your library</button><div class="article-body prose">${markdown(data.content)}</div></div>`;bindGo();typeset();}catch(e){if(state.route==='library/guide')main.innerHTML=`<p class="error-text">${esc(e.message)}</p>`;}return;}if(!lesson){navigate('library');return;}main.innerHTML=`<article class="article-shell"><button class="text-link" data-go="library">← Back to your library</button><header class="article-header"><div class="eyebrow">${esc(lesson.category)} · ${lesson.minutes} MIN READ</div><h1>${esc(lesson.title)}</h1><p>${esc(lesson.description)}</p></header><div class="article-body prose">${markdown(lesson.content)}</div>${lesson.practiceRef?`<div class="hint-box"><strong>From your practice bundles</strong><br>${esc(lesson.practiceRef)}</div>`:''}<div class="article-actions"><button class="button primary" id="lesson-quiz">Quiz me on this ↗</button><button class="button" id="lesson-ask">Explain with AI ✳</button><button class="button ghost" id="lesson-complete">${state.completed.includes(id)?'✓ Completed':'Mark as complete'}</button></div></article>`;bindGo();typeset();$('#lesson-quiz').onclick=()=>{state.quiz=null;state.quizDraft.topic=lesson.title;state.quizDraft.source=state.health?.ready?'ai':'practice';navigate('quiz');};$('#lesson-ask').onclick=()=>askTutor(`Teach me ${lesson.title.toLowerCase()} for the SAT. Explain the idea, walk through an example, and point out common traps.`,id);$('#lesson-complete').onclick=()=>{if(state.completed.includes(id))state.completed=state.completed.filter(x=>x!==id);else state.completed.push(id);save();renderLesson(id);toast(state.completed.includes(id)?'One more concept, one more step forward.':'Lesson marked incomplete.');};}
function renderTutor(){const main=$('#main');main.innerHTML=heading('A LITTLE GUIDANCE. A LOT OF POSSIBILITY.','Let’s figure it out together.','Ask anything. Get a clear explanation, a worked example, and a way to practice.')+`<div class="chat-layout"><section class="chat-panel" aria-label="AI tutor conversation"><div class="chat-top"><div class="tutor-identity"><span class="tutor-icon">✳</span><div>Margin tutor<small>${state.health?.ready?'Ready when you are':'Check connection to start chatting'}</small></div></div><button class="button ghost small" id="new-chat" ${state.chatBusy?'disabled':''}>New conversation +</button></div><div class="chat-messages" id="chat-messages" aria-live="polite"></div><form class="composer" id="chat-form"><textarea id="chat-input" maxlength="6000" placeholder="What would you like to understand?" aria-label="Your question for the AI tutor" ${state.chatBusy?'disabled':''}></textarea><div class="composer-bottom"><span>Enter to send · Shift + Enter for a new line</span><button class="send-button" type="submit" aria-label="Send question" ${state.chatBusy?'disabled':''}>↑</button></div></form></section><aside class="chat-side"><div class="side-box"><h3>How should we learn?</h3><div class="style-options">${[['detailed','Step by step','Go deeper, with examples'],['quick','Keep it simple','The idea, without the detour'],['socratic','Give me a hint','Help me find my own answer']].map(([id,name,desc])=>`<button class="style-option ${state.style===id?'active':''}" data-style="${id}">${name}<span>${desc}</span></button>`).join('')}</div></div><div class="side-box"><h3>A better question, a better answer.</h3><p>Try “I understand factoring, but when do I use the quadratic formula?”<br><br>Choose a question in Your SAT tests, or type a full address: Test 6, Math, Module 1, Question 10. Tell me what you tried so I can explain the exact point that confused you.</p></div><div class="side-box"><h3>Learn it. Then try it.</h3><p>Turn your conversation into a quiz whenever you feel ready.</p><button class="button small" id="chat-to-quiz" style="margin-top:13px">Make a quiz ↗</button></div></aside></div>`;renderMessages();$('#chat-form').onsubmit=e=>{e.preventDefault();const input=$('#chat-input');if(input.value.trim()){sendMessage(input.value.trim());input.value='';}};$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit();}};$('#new-chat').onclick=()=>{if(!state.messages.length)return;if(confirm('Start a new conversation? This clears the chat shown here. Your quizzes and progress stay saved.')){state.messages=[];state.chatError='';state.questionId=null;save();renderTutor();}};$$('[data-style]').forEach(b=>b.onclick=()=>{state.style=b.dataset.style;save();$$('[data-style]').forEach(x=>x.classList.toggle('active',x===b));});$('#chat-to-quiz').onclick=()=>{state.quiz=null;state.quizDraft.topic=state.messages.filter(m=>m.role==='user').at(-1)?.content.slice(0,600)||'';navigate('quiz');};}
function renderMessages(){const box=$('#chat-messages');if(!box)return;box.innerHTML=state.messages.length?state.messages.map((m,i)=>`<div class="message ${m.role}"><div class="message-meta">${m.role==='assistant'?'✳ MARGIN TUTOR':'YOU'}</div><div class="${m.role==='assistant'?'prose':'message-text'}">${m.role==='assistant'?markdown(m.content):esc(m.content)}</div>${m.role==='assistant'?`${m.sources?.length?`<div class="source-list">${m.sources.map(src=>`<a href="${esc(sourceURL(src))}" ${src.url?'target="_blank" rel="noopener"':''}>${esc(src.title)} ↗</a>`).join('')}</div>`:''}<div class="message-actions"><button class="text-link" data-copy="${i}">Copy explanation</button><button class="text-link" data-make="${i}">Practice this →</button></div>`:''}</div>`).join(''):`<div class="chat-welcome"><span class="welcome-symbol">✳</span><h2>No question is too small.</h2><p>A tricky equation? A confusing grammar rule?<br>Let’s break it down into something that makes sense.</p><div class="suggestions">${['Explain quadratics from the beginning','When do I use a semicolon?','Help me stop overthinking reading questions','Make me a study plan for this week'].map(s=>`<button class="suggestion" data-prompt="${esc(s)}">${s} ↗</button>`).join('')}</div></div>`;if(state.chatBusy)box.insertAdjacentHTML('beforeend',`<div class="message assistant" id="streaming-message" ${state.chatPartial?'':'hidden'}><div class="message-meta">✳ MARGIN TUTOR · WRITING</div><div class="message-text streaming-copy" id="streaming-copy">${esc(state.chatPartial)}</div></div><div class="thinking" role="status"><span id="streaming-status">${state.chatPartial?'Explaining…':'Working through your question. This can take a moment…'}</span> ${hosted?'<button class="text-link" id="stop-ai">Stop</button>':''}</div>`);if($('#stop-ai'))$('#stop-ai').onclick=stopBrowserAI;if(state.chatError)box.insertAdjacentHTML('beforeend',`<div class="message-error">${esc(state.chatError)}<br><button class="text-link" id="retry-chat">Try again ↻</button></div>`);$$('[data-prompt]',box).forEach(b=>b.onclick=()=>sendMessage(b.dataset.prompt));$$('[data-copy]',box).forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.messages[+b.dataset.copy].content);toast('Explanation copied.');}catch{toast('Copy unavailable. Select the text to copy it.');}});$$('[data-make]',box).forEach(b=>b.onclick=()=>{state.quiz=null;state.quizDraft.topic=state.messages.slice(0,+b.dataset.make).filter(m=>m.role==='user').at(-1)?.content.slice(0,600)||'Mixed SAT practice';navigate('quiz');});if($('#retry-chat'))$('#retry-chat').onclick=()=>sendMessage(null);typeset(box);box.scrollTop=box.scrollHeight;}
function askTutor(prompt,lessonId){navigate('tutor');setTimeout(()=>sendMessage(prompt,lessonId),30);}
function paintStreamingMessage(partial){const box=$('#chat-messages'),message=$('#streaming-message'),copy=$('#streaming-copy');if(!box||!message||!copy)return;const follow=box.scrollHeight-box.scrollTop-box.clientHeight<80;copy.textContent=partial;message.hidden=!partial;const status=$('#streaming-status');if(status)status.textContent=partial?'Explaining…':'Working through your question. This can take a moment…';if(follow)box.scrollTop=box.scrollHeight;}
async function sendMessage(text,lessonId){if(state.chatBusy)return;if(text){if(/(?:test|bundle)\s*#?\s*\d/i.test(text))state.questionId=null;state.messages.push({role:'user',content:text});save();}if(state.messages.at(-1)?.role!=='user')return;state.chatBusy=true;state.chatError='';state.chatPartial='';if(state.route==='tutor')renderTutor();try{const result=await api('/api/chat',{messages:recentContext(),style:state.style,...(lessonId?{lessonId}:{}),...(state.questionId?{questionId:state.questionId}:{}),learner:learnerContext()},undefined,partial=>{state.chatPartial=partial;if(state.route==='tutor'&&Date.now()-(state.lastPaint||0)>80){state.lastPaint=Date.now();paintStreamingMessage(partial);}});state.messages.push({role:'assistant',content:result.reply,sources:result.sources||[]});state.questionId=result.questionId||null;save();if(state.route!=='tutor')toast('Your tutor’s explanation is ready.');}catch(e){state.chatError=e.message;}finally{state.chatBusy=false;state.chatPartial='';if(state.route==='tutor'){renderTutor();$('#chat-input')?.focus();}}}
function renderQuiz(){if(state.quiz){renderActiveQuiz();return;}const d=state.quizDraft;$('#main').innerHTML=heading('A LITTLE CHALLENGE. A LITTLE GROWTH.','Practice, made personal.','Tell us what you’re working on. We’ll turn it into your next small win.')+`<div class="quiz-layout"><form class="form-card" id="quiz-form"><h2>What’s on your mind?</h2><p>A topic, a skill, or the thing that keeps tripping you up.</p><div class="field"><label for="quiz-topic">What would you like to practice?</label><textarea id="quiz-topic" maxlength="1200" required placeholder="e.g. Quadratic equations, with word problems and tricky answer choices">${esc(d.topic)}</textarea><small>Be as specific as you like. Your prompt guides the questions.</small></div><div class="field-row"><div class="field"><label for="quiz-count">Questions</label><select id="quiz-count">${[3,5,10].map(n=>`<option value="${n}" ${d.count===n?'selected':''}>${n} questions</option>`).join('')}</select></div><div class="field"><label for="quiz-difficulty">Difficulty</label><select id="quiz-difficulty">${['Mixed','Easy','Medium','Hard'].map(x=>`<option ${d.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label for="quiz-source">Practice mode</label><select id="quiz-source"><option value="ai" ${d.source==='ai'?'selected':''}>Custom AI quiz · based on your prompt</option><option value="practice" ${d.source==='practice'?'selected':''}>Practice bank · curated questions</option></select><small id="source-help">${d.source==='ai'?'Original questions created by your connected tutor.':'Filters a small, fixed question bank. Use broad topics like Math or Writing.'}</small></div><div id="quiz-error">${state.quizError?`<p class="error-text">${esc(state.quizError)}</p>`:''}</div><button class="button primary" type="submit" id="generate-quiz" ${state.quizBusy?'disabled':''}>${state.quizBusy?'✳ Creating your questions…':'Generate my quiz'} <span>↗</span></button>${state.quizBusy?'<p class="muted" style="font-size:10px;margin-top:12px">Your local AI is writing and checking the questions. This can take a minute or two.</p>':''}</form><aside class="quiz-aside"><div class="eyebrow">MORE THAN A SCORE</div><h2>Make practice<br>work for you.</h2><ol><li><strong>Make it yours.</strong>Choose a topic and a level that stretches you just a little.</li><li><strong>Think it through.</strong>Try each question before checking the answer. A hint is there if you need it.</li><li><strong>Learn from the why.</strong>See an explanation after every answer, and keep your tricky questions for review.</li></ol><p class="footnote">AI quizzes are original practice. They aren’t official SAT questions or a prediction of your score.</p></aside></div>`;['topic','count','difficulty'].forEach(key=>{const el=$('#quiz-'+key);el.addEventListener('input',()=>{state.quizDraft[key]=key==='count'?+el.value:el.value;});});$('#quiz-source').onchange=e=>{state.quizDraft.source=e.target.value;$('#source-help').textContent=e.target.value==='ai'?'Original questions created by your connected tutor.':'Filters a small, fixed question bank. Use broad topics like Math or Writing.';};$('#quiz-form').onsubmit=async e=>{e.preventDefault();if(state.quizBusy)return;state.quizDraft={topic:$('#quiz-topic').value.trim(),count:+$('#quiz-count').value,difficulty:$('#quiz-difficulty').value,source:$('#quiz-source').value};if(!state.quizDraft.topic)return;state.quizBusy=true;state.quizError='';renderQuiz();try{const result=await api('/api/quiz',state.quizDraft);state.quiz={...result,index:0,selected:null,answers:[],confidence:'',startedAt:Date.now(),questionStarted:Date.now(),checked:false,hint:false,finished:false,saved:false,id:crypto.randomUUID()};if(state.route!=='quiz')toast('Your quiz is ready.');}catch(error){state.quizError=error.message;}finally{state.quizBusy=false;if(state.route==='quiz')renderQuiz();}};}
function renderActiveQuiz(){const quiz=state.quiz;if(quiz.finished){renderResults();return;}const q=quiz.questions[quiz.index];$('#main').innerHTML=`<div class="quiz-shell"><div class="quiz-header"><button class="text-link" id="leave-quiz">← Quiz studio</button><span>${quiz.source==='ai'?'AI-generated practice':'Original practice bank'} · ${esc(q.difficulty||state.quizDraft.difficulty)}</span></div><div class="quiz-progress"><div style="width:${quiz.index/quiz.questions.length*100}%"></div></div><div class="eyebrow">QUESTION ${quiz.index+1} OF ${quiz.questions.length} · ${esc(q.topic||'SAT PRACTICE')}</div><div class="quiz-card"><h2 class="quiz-question">${esc(q.question)}</h2><div class="quiz-choices">${q.choices.map((choice,i)=>`<button class="choice ${quiz.selected===i?'selected':''} ${quiz.checked&&i===q.answerIndex?'correct':''} ${quiz.checked&&quiz.selected===i&&i!==q.answerIndex?'incorrect':''}" data-choice="${i}" ${quiz.checked?'disabled':''} aria-pressed="${quiz.selected===i}"><span class="choice-letter">${'ABCD'[i]}</span><span>${esc(choice)}</span></button>`).join('')}</div>${quiz.hint?`<div class="hint-box">${esc(q.hint||'Identify what the question asks. Write down the rule or relationship that applies before calculating.')}</div>`:''}${quiz.checked?`<div class="quiz-feedback ${quiz.selected!==q.answerIndex?'wrong':''}"><strong>${quiz.selected===q.answerIndex?'✓ You’ve got it.':'A useful moment to learn.'}</strong><div class="prose">${markdown(q.explanation)}</div>${quiz.selected!==q.answerIndex?'<small>This question has been added to your review log.</small>':''}</div>`:''}${!quiz.checked?`<div class="field confidence-field"><label for="quiz-confidence">How sure are you? (optional)</label><select id="quiz-confidence"><option value="">Choose confidence</option><option value="confident" ${quiz.confidence==='confident'?'selected':''}>Confident</option><option value="unsure" ${quiz.confidence==='unsure'?'selected':''}>Unsure</option><option value="guess" ${quiz.confidence==='guess'?'selected':''}>I guessed</option></select></div>`:''}<div class="quiz-controls"><button class="button ghost small" id="quiz-hint" ${quiz.hint||quiz.checked?'disabled':''}>A little hint ✧</button>${quiz.checked?`<button class="button primary" id="next-question">${quiz.index===quiz.questions.length-1?'See my results':'Next question'} →</button>`:`<button class="button primary" id="check-answer" ${quiz.selected===null?'disabled':''}>Check answer →</button>`}</div></div></div>`;if($('#quiz-confidence'))$('#quiz-confidence').onchange=e=>{quiz.confidence=e.target.value;};$$('[data-choice]').forEach(b=>b.onclick=()=>{quiz.selected=+b.dataset.choice;renderActiveQuiz();});$('#quiz-hint').onclick=()=>{quiz.hint=true;renderActiveQuiz();};$('#leave-quiz').onclick=()=>{if(confirm('Leave this quiz? Missed questions stay in your review log, but this unfinished quiz will not count toward your results.')){state.quiz=null;renderQuiz();}};if($('#check-answer'))$('#check-answer').onclick=()=>{if(quiz.selected===null||quiz.checked)return;quiz.checked=true;quiz.answers.push({selected:quiz.selected,correct:quiz.selected===q.answerIndex,usedHint:quiz.hint,confidence:quiz.confidence||'',seconds:Math.round((Date.now()-(quiz.questionStarted||Date.now()))/1000)});if(quiz.selected!==q.answerIndex||quiz.hint||['unsure','guess'].includes(quiz.confidence)){state.mistakes.unshift({...q,id:`${quiz.id}-${quiz.index}`,selected:quiz.selected,reason:quiz.selected!==q.answerIndex?'Incorrect answer':quiz.hint?'Used a hint':quiz.confidence==='guess'?'Correct guess':'Correct but unsure',date:new Date().toISOString(),resolved:false,source:quiz.source});save();renderNav();}renderActiveQuiz();};if($('#next-question'))$('#next-question').onclick=()=>{if(quiz.index===quiz.questions.length-1){quiz.finished=true;renderResults();}else{quiz.index++;quiz.checked=false;quiz.selected=null;quiz.hint=false;quiz.confidence='';quiz.questionStarted=Date.now();renderActiveQuiz();}window.scrollTo(0,0);};typeset();}
function renderResults(){const quiz=state.quiz;const score=quiz.answers.filter(a=>a.correct).length;if(!quiz.saved){state.history.unshift({id:quiz.id,title:quiz.title||state.quizDraft.topic,score,total:quiz.questions.length,date:new Date().toISOString(),source:quiz.source,domains:domainResults(quiz),seconds:quiz.answers.reduce((n,a)=>n+(a.seconds||0),0),independent:quiz.answers.filter(a=>a.correct&&!a.usedHint&&!['guess','unsure'].includes(a.confidence)).length,hints:quiz.answers.filter(a=>a.usedHint).length});quiz.saved=true;save();}$('#main').innerHTML=`<div class="quiz-shell"><div class="score-panel"><div class="eyebrow">ANOTHER STEP FORWARD</div><div class="score-orb">${score}<span style="font-size:20px;color:#a2ac94">/${quiz.questions.length}</span></div><h1>${score===quiz.questions.length?'That’s a strong foundation.':'Now you know what’s next.'}</h1><p>${esc(quiz.title||state.quizDraft.topic)}<br>${quiz.answers.filter(a=>a.usedHint).length} hints used · ${quiz.answers.filter(a=>['guess','unsure'].includes(a.confidence)).length} guesses or unsure answers · Practice accuracy, not an SAT score prediction.</p><div class="inline-actions" style="justify-content:center"><button class="button primary" id="new-quiz">Make another quiz ↗</button><button class="button" data-go="review">Review my progress</button></div></div>${quiz.diagnostic?`<div class="domain-results">${domainResults(quiz).map(d=>`<div class="stat-card"><strong>${d.correct}/${d.total}</strong><span>${esc(d.domain)} · ${d.hints} hints used</span></div>`).join('')}</div><p class="footnote">Two questions per domain suggest where to start. This is a small sample, not proof of mastery or an SAT score estimate.</p>`:''}<div class="section-top"><h2>A closer look at your answers</h2></div>${quiz.questions.map((q,i)=>`<details class="result-row"><summary>${quiz.answers[i].correct?'✓':'○'} ${i+1}. ${esc(q.question)}</summary><p>Your answer: ${esc(q.choices[quiz.answers[i].selected])} · ${quiz.answers[i].seconds||0}s${quiz.answers[i].confidence?' · '+esc(quiz.answers[i].confidence):''}<br>Correct answer: ${esc(q.choices[q.answerIndex])}</p><div class="prose">${markdown(q.explanation)}</div></details>`).join('')}</div>`;$('#new-quiz').onclick=()=>{state.quiz=null;renderQuiz();};bindGo();typeset();}
function renderReview(){const total=state.history.reduce((n,h)=>n+h.total,0);const correct=state.history.reduce((n,h)=>n+h.score,0);const mistakes=state.mistakes.filter(m=>!m.resolved);$('#main').innerHTML=heading('LOOK HOW FAR YOU’RE COMING','Progress lives in the details.','Your completed quizzes, lessons, and the questions worth another look.')+`<div class="stat-grid"><div class="stat-card"><strong>${state.history.length}</strong><span>Quizzes completed</span></div><div class="stat-card"><strong>${total?Math.round(correct/total*100)+'%':'—'}</strong><span>Practice accuracy</span></div><div class="stat-card"><strong>${state.completed.length}</strong><span>Lessons completed</span></div></div>${renderSkillMap()}<div class="section-top"><h2>Your review log</h2><span class="chip">${mistakes.length} to revisit</span></div>${mistakes.length?mistakes.map(q=>`<article class="review-card"><div class="eyebrow">${esc(q.topic||'SAT PRACTICE')} · ${esc(q.source==='ai'?'AI PRACTICE':'ORIGINAL PRACTICE')}</div><h3>${esc(q.question)}</h3><p>Your answer: ${esc(q.choices[q.selected])} · ${esc(q.reason||'Incorrect answer')}</p><details><summary class="text-link">See answer and explanation</summary><p><strong>${esc(q.choices[q.answerIndex])}</strong></p><div class="prose">${markdown(q.explanation)}</div></details><div class="inline-actions"><button class="button small" data-resolve="${esc(q.id)}">I understand this now ✓</button><button class="button ghost small" data-review-ask="${esc(q.id)}">Work through it with AI ↗</button></div></article>`).join(''):`<div class="empty-state"><div class="empty-symbol">✧</div><h2>${state.mistakes.length?'A little clearer, every day.':'A fresh page for your progress.'}</h2><p>${state.mistakes.length?'You’ve reviewed every question in your log. Try a fresh quiz to check what stuck.':'Misses, guesses, uncertain answers, and questions answered with hints will appear here, with explanations to help you get them next time.'}</p><button class="button primary" data-go="quiz">Try a quiz ↗</button></div>`}${state.history.length?`<div class="section-top"><h2>Recent practice</h2></div><div class="path-card">${state.history.slice(0,8).map(h=>`<div class="path-row"><span class="path-num">${h.score}/${h.total}</span><div><h3>${esc(h.title)}</h3><p>${new Date(h.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${h.source==='ai'?'AI practice':'Original practice bank'}</p></div></div>`).join('')}</div>`:''}`;bindGo();$$('[data-resolve]').forEach(b=>b.onclick=()=>{const q=state.mistakes.find(q=>q.id===b.dataset.resolve);q.resolved=true;save();renderNav();renderReview();toast('Reviewed. Try a similar question later to check your understanding.');});$$('[data-review-ask]').forEach(b=>b.onclick=()=>{const q=state.mistakes.find(q=>q.id===b.dataset.reviewAsk);askTutor(`Help me understand this SAT practice question.\n\n${q.question}\n${q.choices.map((c,i)=>`${'ABCD'[i]}) ${c}`).join('\n')}\n\nI chose ${'ABCD'[q.selected]}. The practice key says ${'ABCD'[q.answerIndex]}. Please check the answer independently, then explain how to solve it and avoid my mistake.`);});typeset();}
function renderRoute(){state.route=(location.hash.slice(1)||'home');renderNav();if(state.route==='home')renderHome();else if(state.route==='grammar')renderGrammar($('#main'));else if(state.route==='tutor')renderTutor();else if(state.route==='quiz')renderQuiz();else if(state.route==='library')renderLibrary();else if(state.route.startsWith('library/'))renderLesson(state.route.slice(8));else if(state.route==='bundles')renderBundles();else if(state.route==='plan')renderPlan();else if(state.route==='review')renderReview();else navigate('home');window.scrollTo(0,0);}
$('#settings-button').onclick=$('#connection-button').onclick=()=>{$('#settings-dialog').showModal();checkHealth();};$('.dialog-close').onclick=()=>$('#settings-dialog').close();$('#settings-dialog').onclick=e=>{if(e.target===$('#settings-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};$('#recheck').onclick=async()=>{const b=$('#recheck');b.disabled=true;await checkHealth();b.disabled=false;};
async function init(){try{const result=await api('/api/library');state.lessons=result.lessons||[];await checkHealth();renderRoute();window.addEventListener('hashchange',renderRoute);}catch(e){$('#main').innerHTML=`<div class="empty-state"><h2>Let’s reconnect.</h2><p>${esc(e.message)}</p><button class="button primary" id="reload-app">Try again</button></div>`;$('#reload-app').onclick=()=>location.reload();}}
init();

function learnerContext(){
  const topics=[...new Set(state.mistakes.filter(m=>!m.resolved).map(m=>m.topic))];
  const recent=state.officialLog.filter(m=>!m.correct||m.confidence==='guess').slice(0,5);
  return {goal:state.profile.goal||'Build understanding in SAT Math and Reading and Writing',weakTopics:topics.join(', '),recentMistakes:recent.map(m=>`${m.address}: ${m.reason||'needs review'}`).join('; ')};
}
async function renderBundles(){
  const main=$('#main');main.innerHTML='<div class="loading">Opening your SAT bundles…</div>';
  try{if(!state.bundles)state.bundles=await api('/api/bundles');if(state.route!=='bundles')return;
    if(!state.bundles.count){main.innerHTML=heading('YOUR ORIGINAL FILES','No bundles imported yet.','Run the SAT bundle importer to add your local PDFs.');return;}
    const d=state.bundleChoice;
    main.innerHTML=heading('YOUR ORIGINAL COLLEGE BOARD MATERIALS','The question. The reasoning. The breakthrough.',`${state.bundles.count} questions from your eight SAT bundles, with the original diagrams and official explanations.`)+`<div class="bundle-toolbar form-card"><div class="field-row"><div class="field"><label for="bundle-test">Test</label><select id="bundle-test">${[...new Set(state.bundles.questions.map(q=>q.test))].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${n===d.test?'selected':''}>Test ${n}</option>`).join('')}</select></div><div class="field"><label for="bundle-section">Section</label><select id="bundle-section"><option value="math" ${d.section==='math'?'selected':''}>Math</option><option value="rw" ${d.section==='rw'?'selected':''}>Reading & Writing</option></select></div><div class="field"><label for="bundle-module">Module</label><select id="bundle-module">${[1,2].map(n=>`<option ${n===d.module?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="bundle-number">Question</label><select id="bundle-number">${Array.from({length:d.section==='math'?27:33},(_,i)=>i+1).map(n=>`<option ${n===d.number?'selected':''}>${n}</option>`).join('')}</select></div></div><p class="footnote">These are nonadaptive paper practice tests. Use Bluebook for digital timing and adaptive test practice.</p><div class="inline-actions bundle-downloads"><a class="text-link" href="${assetURL(`sat-practice-test-${d.test}-digital.pdf`)}" target="_blank" rel="noopener">Full test PDF ↗</a><a class="text-link" href="${assetURL(`sat-practice-test-${d.test}-answers-digital.pdf`)}" target="_blank" rel="noopener">All answer explanations ↗</a><a class="text-link" href="${assetURL(`scoring-sat-practice-test-${d.test}-digital.pdf`)}" target="_blank" rel="noopener">Official scoring guide ↗</a></div></div><div id="official-workspace"></div>`;
    for(const key of ['test','section','module','number'])$('#bundle-'+key).onchange=e=>{state.bundleChoice[key]=key==='section'?e.target.value:+e.target.value;state.bundleChoice.number=Math.min(state.bundleChoice.number,state.bundleChoice.section==='math'?27:33);state.officialReveal=false;renderBundles();};
    const id=`t${d.test}-${d.section}-m${d.module}-q${d.number}`;
    const q=await api('/api/bundle-question?id='+encodeURIComponent(id));
    if(state.route!=='bundles'||id!==`t${state.bundleChoice.test}-${state.bundleChoice.section}-m${state.bundleChoice.module}-q${state.bundleChoice.number}`)return;
    state.official=q;renderOfficial();
  }catch(e){if(state.route==='bundles')main.innerHTML=`<p class="error-text">${esc(e.message)}</p>`;}
}
function renderOfficial(){
  const q=state.official;if(!q||!$('#official-workspace'))return;
  const saved=state.officialLog.find(m=>m.questionId===q.id);
  $('#official-workspace').innerHTML=`<div class="official-layout"><article class="official-card"><div class="eyebrow">${esc(q.address)}</div><img class="question-image" src="${assetURL(q.image)}" alt="Original question: ${esc(q.address)}"><details class="extracted-text"><summary>Text version (notation may be incomplete)</summary><pre>${esc(q.text)}</pre></details><div class="inline-actions">${q.sources.map(s=>`<a class="text-link" href="${esc(sourceURL(s))}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('')}</div></article><aside class="official-side form-card"><h2>Try it first.</h2><p>Put your thinking into words. Your tutor can help with the step that got confusing.</p><div class="field"><label for="official-attempt">Your answer or working</label><textarea id="official-attempt" maxlength="2000" placeholder="I chose B because… / I got x = 4, but…"></textarea></div><div class="field"><label for="official-confidence">How sure are you?</label><select id="official-confidence"><option value="unsure">Somewhat unsure</option><option value="confident">Confident</option><option value="guess">I guessed</option></select></div><div class="inline-actions"><button class="button" id="official-hint" ${state.chatBusy?'disabled':''}>Help me start</button><button class="button primary" id="official-ask" ${state.chatBusy?'disabled':''}>Explain this question ↗</button></div><button class="text-link reveal-link" id="official-reveal">${state.officialReveal?'Hide explanation':'Check official explanation ↓'}</button>${state.officialReveal?`<div class="official-explanation prose">${q.explanationImages?.length?q.explanationImages.map(file=>`<img class="answer-image" src="${assetURL(file)}" alt="Official Math explanation for ${esc(q.address)}">`).join(''):markdown(q.explanation)}</div><div class="field"><label for="official-reason">What should you review?</label><select id="official-reason"><option>Concept or rule</option><option>Misread the question</option><option>Arithmetic or algebra</option><option>Passage evidence</option><option>Answer choice trap</option><option>Timing</option><option>Nothing — understood it</option></select></div><div class="inline-actions"><button class="button small" id="official-correct">Got it right</button><button class="button small" id="official-missed">Missed it / unsure</button></div>`:''}${saved?`<details class="extracted-text"><summary>Your previous attempt</summary><pre>${esc(saved.attempt)}</pre></details><p class="footnote">Last review: ${saved.correct?'correct':'needs practice'} · ${esc(saved.reason)}. ${saved.due?`Next review ${new Date(saved.due).toLocaleDateString()}.`:''}</p>`:''}<div class="inline-actions question-next"><button class="button ghost small" id="official-prev" ${q.number===1?'disabled':''}>← Previous</button><button class="button small" id="official-next" ${q.number===(q.section==='math'?27:33)?'disabled':''}>Next →</button></div></aside></div>`;
  if(saved?.confidence)$('#official-confidence').value=saved.confidence;
  $('#official-reveal').onclick=()=>{const value=$('#official-attempt').value;const confidence=$('#official-confidence').value;state.officialReveal=!state.officialReveal;renderOfficial();$('#official-attempt').value=value;$('#official-confidence').value=confidence;};
  function tutor(hint){const attempt=$('#official-attempt').value.trim();state.style=hint?'socratic':'detailed';state.questionId=q.id;save();askTutor(`${q.address.replaceAll(' · ', ', ')}. ${hint?'Please give me one clue without revealing the answer.':'Please explain this exact question step by step, teach the rule, and show how to avoid the tempting wrong answer.'}${attempt?'\nMy attempt: '+attempt:''}`);}
  $('#official-hint').onclick=()=>tutor(true);$('#official-ask').onclick=()=>tutor(false);
  for(const [id,delta] of [['prev',-1],['next',1]])$('#official-'+id).onclick=()=>{state.bundleChoice.number+=delta;state.officialReveal=false;renderBundles();};
  function log(correct){const previous=state.officialLog.find(m=>m.questionId===q.id);const streak=correct&&$('#official-confidence').value==='confident'?(previous?.streak||0)+1:0;const days=streak?Math.min(30,3**Math.min(streak,3)):1;const row={questionId:q.id,address:q.address,section:q.section,attempt:$('#official-attempt').value,correct,confidence:$('#official-confidence').value,reason:$('#official-reason').value,date:new Date().toISOString(),due:new Date(Date.now()+days*86400000).toISOString(),streak};state.officialLog=state.officialLog.filter(m=>m.questionId!==q.id);state.officialLog.unshift(row);save();renderOfficial();toast(`Saved. Try this again in ${days} day${days===1?'':'s'} without the explanation.`);}
  if($('#official-correct'))$('#official-correct').onclick=()=>log(true);if($('#official-missed'))$('#official-missed').onclick=()=>log(false);typeset();
}
function renderPlan(){
  const weak=state.mistakes.filter(m=>!m.resolved);const due=state.officialLog.filter(m=>new Date(m.due)<=new Date());
  const topics=[...new Set(weak.map(m=>m.topic))];const daysToTest=state.profile.testDate?Math.ceil((new Date(state.profile.testDate+'T23:59:59')-Date.now())/86400000):null;const minutes=+state.profile.minutes||45;
  const recall=Math.max(5,Math.round(minutes*.15)),learn=Math.round(minutes*.25),practice=Math.round(minutes*.35),review=minutes-recall-learn-practice;
  $('#main').innerHTML=heading('UNDERSTAND. RETRIEVE. APPLY. REPEAT.','A plan that changes with your practice.',daysToTest!==null?`${daysToTest>0?daysToTest+' days until your test.':'Update your test date for a new plan.'} ${daysToTest>0&&daysToTest<=7?'Prioritize familiar weak skills, pacing, and sleep this week.':'Build understanding, then solve without help.'}`:'Start with evidence from your mistakes. Finish by solving without help.')+`<form class="form-card plan-settings" id="plan-settings"><div class="field-row"><div class="field"><label for="plan-minutes">Daily study time</label><select id="plan-minutes">${[20,30,45,60,90].map(n=>`<option value="${n}" ${minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><div class="field"><label for="plan-date">Test date (optional)</label><input id="plan-date" type="date" value="${esc(state.profile.testDate)}"></div><div class="field"><label for="plan-goal">Your goal</label><input id="plan-goal" maxlength="200" placeholder="e.g. Stop guessing on grammar" value="${esc(state.profile.goal)}"></div></div><button class="button small" type="submit">Update my plan</button></form><div class="plan-grid"><section><div class="section-top"><h2>Today’s ${minutes}-minute session</h2></div><div class="path-card">${[[recall,'Recall before rereading',due.length?`${due.length} official questions are due. Solve them again with the explanation closed.`:'Write a rule or formula from memory. Reattempt one previous mistake.'],[learn,'Repair one specific skill',topics.length?`Your review log points to: ${topics.slice(0,3).join(', ')}. Pick one and study the matching lesson.`:'Begin with linear equations in Math or sentence boundaries in Writing. Use practice to find your next priority.'],[practice,'Solve independently','Attempt a short set from your bundles. Record your answer and confidence before checking. Alternate Math and Reading and Writing across days.'],[review,'Explain the mistake','Name the cause. Write a one-sentence rule. Solve a similar question tomorrow, then revisit it after 3, 9, and 27 days as confidence improves.']].map(([time,title,desc],i)=>`<div class="path-row"><span class="path-num">${time}m</span><div><h3>${title}</h3><p>${desc}</p></div></div>`).join('')}</div><div class="inline-actions"><button class="button primary" data-go="bundles">Work on an official question ↗</button><button class="button" data-go="library">Find a lesson</button></div></section><aside class="tip-card"><div class="eyebrow">YOUR NEXT PRIORITY</div><h2>${topics.length?esc(topics[0]):'Find your starting point.'}</h2><p>${topics.length?'This topic appears in your unresolved quiz mistakes. Learn the rule, then prove you can apply it without a hint.':'Take a mixed practice-bank quiz, then review both misses and guesses. A short quiz identifies starting points; it does not predict an SAT score.'}</p><button class="button small" data-go="quiz">Start a short quiz ↗</button></aside></div><div class="section-top"><h2>Official question review</h2><span class="chip">${due.length} due today</span></div>${state.officialLog.length?state.officialLog.map(m=>`<article class="review-card"><div class="eyebrow">${m.correct&&m.confidence==='confident'?'CORRECT & CONFIDENT':'REVISIT THIS SKILL'}</div><h3>${esc(m.address)}</h3><p>${esc(m.reason)} · Next review ${new Date(m.due).toLocaleDateString()}</p><button class="button small" data-official-review="${esc(m.questionId)}">Try again without help ↗</button></article>`).join(''):'<div class="hint-box">No official attempts recorded yet. Open a question in Your SAT tests, attempt it, check the official explanation, and record your result.</div>'}<div class="section-top"><h2>Your weekly rhythm</h2></div><div class="path-card"><div class="path-row"><span class="path-num">1–4</span><div><h3>Build and repair</h3><p>Alternate Math and Reading and Writing. Spend most of the session on the skill your errors expose.</p></div></div><div class="path-row"><span class="path-num">5</span><div><h3>Mix and retrieve</h3><p>Mix skills so you have to recognize the method. Include past questions without consulting their solutions.</p></div></div><div class="path-row"><span class="path-num">6</span><div><h3>Practice the actual format</h3><p>Use official Bluebook adaptive practice when you can complete a full test. Reserve the next session for reviewing misses and guesses.</p></div></div><div class="path-row"><span class="path-num">7</span><div><h3>Review and recover</h3><p>Repair the highest-impact errors. Take a lighter day so your next session is focused.</p></div></div></div><p class="footnote">The standard digital SAT uses two 32-minute Reading and Writing modules and two 35-minute Math modules. Your paper bundles have more questions and are nonadaptive. <a href="https://satsuite.collegeboard.org/sat/whats-on-the-test/structure" target="_blank" rel="noopener">Official format ↗</a> · <a href="https://satsuite.collegeboard.org/practice/practice-tests" target="_blank" rel="noopener">Bluebook practice ↗</a></p>`;
  $('#plan-settings').onsubmit=e=>{e.preventDefault();state.profile={minutes:+$('#plan-minutes').value,testDate:$('#plan-date').value,goal:$('#plan-goal').value};save();renderPlan();toast('Your study plan is updated.');};
  $$('[data-official-review]').forEach(b=>b.onclick=()=>{const [,test,section,module,number]=b.dataset.officialReview.match(/^t(\d+)-(math|rw)-m(\d)-q(\d+)$/);state.bundleChoice={test:+test,section,module:+module,number:+number};state.officialReveal=false;navigate('bundles');});bindGo();
}
$('#start-browser-ai').onclick=async()=>{
  const b=$('#start-browser-ai'),progress=$('#ai-download-status');b.disabled=true;
  try{progress.textContent='Checking your device…';await startBrowserAI($('#ai-model').value,report=>{progress.textContent=report.text;$('#ai-download-progress').value=Math.max(0,Math.min(1,report.progress||0));});await checkHealth();progress.textContent='Your tutor is ready. Open AI tutor or choose an official question.';toast('Your browser AI is ready.');}catch(e){progress.textContent=e.message;await checkHealth();}finally{b.disabled=false;}
};
if(!hosted)$('#browser-ai-settings').hidden=true;
function domainResults(quiz){const map=new Map();quiz.questions.forEach((q,i)=>{const domain=q.domain||q.category||q.topic;const row=map.get(domain)||{domain,correct:0,total:0,hints:0};row.total++;if(quiz.answers[i]?.correct)row.correct++;if(quiz.answers[i]?.usedHint)row.hints++;map.set(domain,row);});return [...map.values()];}
async function startDiagnostic(){try{const result=await api('/api/diagnostic');state.quiz={...result,index:0,selected:null,answers:[],confidence:'',startedAt:Date.now(),questionStarted:Date.now(),checked:false,hint:false,finished:false,saved:false,id:crypto.randomUUID()};navigate('quiz');}catch(e){toast(e.message);}}
$('#export-progress').onclick=()=>{const progress={questionId:state.questionId,profile:state.profile,officialLog:state.officialLog,messages:state.messages.slice(-30),history:state.history.slice(0,100),mistakes:state.mistakes.slice(0,200),completed:state.completed,style:state.style};const content=JSON.stringify({version:2,exportedAt:new Date().toISOString(),progress},null,2);$('#progress-backup-download')?.remove();const a=document.createElement('a');a.id='progress-backup-download';a.hidden=true;a.href='data:application/json;charset=utf-8,'+encodeURIComponent(content);a.download=`margin-progress-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),60000);toast('Your progress backup is downloaded.');};
$('#import-progress').onclick=()=>$('#progress-file').click();
$('#progress-file').onchange=async e=>{try{
 const file=e.target.files[0];if(!file)return;if(file.size>15000000)throw Error('This backup is too large.');const backup=JSON.parse(await file.text());if(backup.version!==2||!backup.progress||typeof backup.progress!=='object')throw Error('Choose a Margin progress backup.');const p=backup.progress;
 const text=(v,n=1000)=>typeof v==='string'?v.slice(0,n):'';const array=v=>Array.isArray(v)?v:[];const date=v=>Number.isFinite(Date.parse(v))?new Date(v).toISOString():new Date().toISOString();
 const messages=array(p.messages).filter(m=>m&&['user','assistant'].includes(m.role)&&typeof m.content==='string').slice(-30).map(m=>({role:m.role,content:text(m.content,m.role==='user'?6000:16000),sources:array(m.sources).filter(s=>s&&typeof s.id==='string').map(s=>({id:text(s.id,100),title:text(s.title,180),url:text(s.url,300)}))}));
 const mistakes=array(p.mistakes).filter(q=>q&&typeof q.question==='string'&&Array.isArray(q.choices)&&q.choices.length===4&&q.choices.every(c=>typeof c==='string')&&Number.isInteger(q.answerIndex)&&q.answerIndex>=0&&q.answerIndex<4&&Number.isInteger(q.selected)&&q.selected>=0&&q.selected<4).slice(0,200).map(q=>({id:text(q.id,100),question:text(q.question,5000),choices:q.choices.map(c=>text(c,2000)),answerIndex:q.answerIndex,selected:q.selected,topic:text(q.topic,200),explanation:text(q.explanation,5000),reason:text(q.reason,100),source:q.source==='ai'?'ai':'practice',date:date(q.date),resolved:!!q.resolved}));
 const history=array(p.history).filter(h=>h&&Number.isInteger(h.total)&&h.total>0&&h.total<=100&&Number.isInteger(h.score)&&h.score>=0&&h.score<=h.total).slice(0,100).map(h=>({id:text(h.id,100),title:text(h.title,180),total:h.total,score:h.score,hints:Number.isInteger(h.hints)?Math.max(0,Math.min(h.total,h.hints)):0,source:h.source==='ai'?'ai':'practice',seconds:Number.isFinite(h.seconds)?Math.max(0,h.seconds):0,independent:Number.isFinite(h.independent)?Math.max(0,Math.min(h.total,h.independent)):0,domains:array(h.domains).filter(d=>d&&typeof d.domain==='string'&&Number.isInteger(d.total)&&d.total>0&&Number.isInteger(d.correct)&&d.correct>=0&&d.correct<=d.total).map(d=>({domain:text(d.domain,100),total:d.total,correct:d.correct,hints:Number.isFinite(d.hints)?Math.max(0,Math.min(d.total,d.hints)):0})),date:date(h.date)}));
 const officialLog=array(p.officialLog).filter(m=>m&&/^t(?:[4-9]|10|11)-(?:math|rw)-m[12]-q\d+$/.test(m.questionId)).slice(0,960).map(m=>({questionId:m.questionId,address:text(m.address,200),section:m.section==='math'?'math':'rw',attempt:text(m.attempt,2000),reason:text(m.reason,100),correct:!!m.correct,confidence:['confident','guess','unsure'].includes(m.confidence)?m.confidence:'unsure',date:date(m.date),due:date(m.due),streak:Number.isInteger(m.streak)?Math.max(0,Math.min(3,m.streak)):0}));
 if(!confirm('Restore this backup? It will replace the progress and conversation in this browser. Download your current backup first if you want to keep it.'))return;
 Object.assign(state,{messages,mistakes,history,officialLog,questionId:null,completed:array(p.completed).filter(id=>state.lessons.some(l=>l.id===id)),style:['detailed','quick','socratic'].includes(p.style)?p.style:'detailed',profile:{minutes:[20,30,45,60,90].includes(p.profile?.minutes)?p.profile.minutes:45,goal:text(p.profile?.goal,200),testDate:/^\d{4}-\d{2}-\d{2}$/.test(p.profile?.testDate||'')?p.profile.testDate:''},quiz:null});save();renderRoute();toast('Progress restored from your backup.');
 }catch(e){toast(e.message||'Could not read this backup.');}finally{e.target.value='';}};
function renderSkillMap(){
 const domains=['Algebra','Advanced Math','Problem-Solving & Data Analysis','Geometry & Trigonometry','Information & Ideas','Craft & Structure','Expression of Ideas','Standard English Conventions'];
 const rows=domains.map(domain=>{const samples=state.history.flatMap(h=>h.domains||[]).filter(d=>d.domain===domain);return {domain,correct:samples.reduce((n,d)=>n+d.correct,0),total:samples.reduce((n,d)=>n+d.total,0),hints:samples.reduce((n,d)=>n+(d.hints||0),0)};});
 return `<div class="section-top"><h2>Your skill signals</h2><button class="text-link" id="start-diagnostic">Take the skill check →</button></div><p class="footnote">Accuracy from your recorded diagnostics. Small samples suggest starting points; they do not establish mastery or predict scores.</p><div class="skill-grid">${rows.map(d=>`<div class="skill-card"><h3>${esc(d.domain)}</h3><div class="skill-meter"><div style="width:${d.total?d.correct/d.total*100:0}%"></div></div><p>${d.total?`${d.correct}/${d.total} correct · ${d.hints} hints used`:'No diagnostic attempts yet'}</p></div>`).join('')}</div>`;
}
